import { formatParseError, parseArgs, renderHelp } from "./lib/argparse_like.mjs";
import { Money } from "./lib/money.mjs";

function getProgramName(scriptPath) {
  if (!scriptPath) {
    return "test6.mjs";
  }

  const normalized = scriptPath.replace(/\\/g, "/");
  const parts = normalized.split("/");
  const lastPart = parts[parts.length - 1];

  return lastPart || "test6.mjs";
}

const programName = getProgramName(process.argv[1]);

