import { isArgparseNegativeNumberToken, parsePythonFloatLiteral } from "./float_parser.mjs";

const OPTIONS = [
  { longName: "help", shortName: "h", kind: "flag" },
  { longName: "amount", kind: "float" },
  { longName: "currency", kind: "string" },
];

function usageLine(programName) {
  return `usage: ${programName} [-h] --amount AMOUNT --currency CURRENCY`;
}

function makeParseError(message) {
  const error = new Error(message);
  error.name = "ArgparseError";
  return error;
}

function findLongOption(name) {
  const matches = OPTIONS.filter((option) => option.longName.startsWith(name));
  return matches.length === 1 ? matches[0] : null;
}

function tokenLooksLikeMissingArgument(token) {
  return token.startsWith("-") && token !== "-" && !isArgparseNegativeNumberToken(token);
}

function missingRequiredMessage(missingOptions) {
  return `the following arguments are required: ${missingOptions.join(", ")}`;
}

function convertOptionValue(option, rawValue) {
  if (option.kind === "string") {
    return rawValue;
  }

  const parsed = parsePythonFloatLiteral(rawValue);

  if (!parsed.ok) {
    throw makeParseError(`argument --${option.longName}: invalid float value: '${rawValue}'`);
  }

  return parsed.value;
}

function parseLongToken(token) {
  const separatorIndex = token.indexOf("=");

  if (separatorIndex === -1) {
    return {
      name: token.slice(2),
      explicitValue: null,
    };
  }

  return {
    name: token.slice(2, separatorIndex),
    explicitValue: token.slice(separatorIndex + 1),
  };
}

export function renderHelp(programName) {
  return `${usageLine(programName)}\n\noptions:\n  -h, --help           show this help message and exit\n  --amount AMOUNT\n  --currency CURRENCY\n`;
}

export function formatParseError(programName, message) {
  return `${usageLine(programName)}\n${programName}: error: ${message}\n`;
}

export function parseArgs(argv, programName) {
  const parsedValues = {
    amount: undefined,
    currency: undefined,
  };
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === "--") {
      extras.push(...argv.slice(index + 1));
      break;
    }

    if (token === "-h" || (token.startsWith("-h") && !token.startsWith("-h="))) {
      return { help: true };
    }

    if (token.startsWith("-h=")) {
      throw makeParseError(`argument -h/--help: ignored explicit argument '${token.slice(3)}'`);
    }

    if (token.startsWith("--") && token.length > 2) {
      const { name, explicitValue } = parseLongToken(token);
      const option = findLongOption(name);

      if (!option) {
        extras.push(token);
        continue;
      }

      if (option.kind === "flag") {
        if (explicitValue !== null) {
          throw makeParseError(`argument -h/--help: ignored explicit argument '${explicitValue}'`);
        }

        return { help: true };
      }

      let rawValue = explicitValue;

      if (rawValue === null) {
        const nextToken = argv[index + 1];

        if (nextToken === undefined || tokenLooksLikeMissingArgument(nextToken)) {
          throw makeParseError(`argument --${option.longName}: expected one argument`);
        }

        rawValue = nextToken;
        index += 1;
      }

      parsedValues[option.longName] = convertOptionValue(option, rawValue);
      continue;
    }

    if (token.startsWith("-") && token !== "-") {
      extras.push(token);
      continue;
    }

    extras.push(token);
  }

  const missingOptions = [];

  if (parsedValues.amount === undefined) {
    missingOptions.push("--amount");
  }

  if (parsedValues.currency === undefined) {
    missingOptions.push("--currency");
  }

  if (missingOptions.length > 0) {
    throw makeParseError(missingRequiredMessage(missingOptions));
  }

  if (extras.length > 0) {
    throw makeParseError(`unrecognized arguments: ${extras.join(" ")}`);
  }

  return {
    help: false,
    values: parsedValues,
  };
}

